/** The plain news in one sentence, or null. Returns { id, tone, lines: [mild, middle, csuite] }. */
export function readNews(sentence) {
  const s = String(sentence ?? "").trim();
  if (!s || s.length > 400) return null;
  for (const r of RULES) {
    const m = s.match(r.re);
    if (!m) continue;
    if (r.unless && r.unless.test(s)) continue;
    if (r.when && !r.when(s)) continue;
    let out;
    try { out = r.build(s, m); } catch { out = null; }
    const lines = Array.isArray(out) ? out : out?.lines;
    if (!lines || lines.some((x) => !x || /undefined|null/.test(x))) continue;
    const res = { broad: !!r.broad, id: out?.id ?? r.id, tone: out?.id && out.id !== r.id ? (NEWS_TONE[out.id] ?? r.tone) : r.tone, lines };
    // Round 10c: a sentence that also says jobs are ending is about layoffs; a closed perk is a benefit cut; remote roles ending is return to office.
    {
      const over = res.id === "shutdown" ? ["layoffs", "rto", "benefits"] : res.id === "delay" ? ["layoffs", "problem", "benefits", "budget-freeze"] : res.id === "benefits" ? ["rto"] : res.id === "good-news" ? ["performance"] : /^(?:reorg|hedge|budget-freeze|cost-cuts|departure)$/.test(res.id) ? ["layoffs"] : [];
      for (const id of over) for (const b of RULES.filter((x) => x.broad && x.id === id)) { if (b && b !== r && b.re.test(s) && !(b.unless && b.unless.test(s))) { const bo = b.build(s, s.match(b.re)); if (Array.isArray(bo) && bo.every((x) => x && !/undefined|null/.test(x))) return { broad: true, id, tone: b.tone, lines: bo }; } }
    }
    return res;
    return { broad: !!r.broad, id: out?.id ?? r.id, tone: out?.id && out.id !== r.id ? (NEWS_TONE[out.id] ?? r.tone) : r.tone, lines };
  }
  return null;
}

const NEWS_TONE = { benefits: "bad" };
export const NEWS_SIGNALS = {
  "good-news": { label: "Good news", tone: "good" },
  fyi: { label: "Just an FYI", tone: "none" },
  "cost-increase": { label: "It costs more", tone: "bad" },
  problem: { label: "Something went wrong", tone: "bad" },
  hedge: { label: "Vague on purpose", tone: "warn" },
  rejection: { label: "The answer is no", tone: "bad" },
};
// Bad news outranks a hedge, and both outrank good news when one memo has several.
export const NEWS_RANK = { rejection: 6, "layoff-you": 10, layoffs: 9, pip: 8, shutdown: 7, "cost-increase": 6, benefits: 6, "no-raises": 6, "hiring-freeze": 5, "budget-freeze": 5, rto: 5, delay: 5, problem: 5, departure: 4, reorg: 4, performance: 4, hedge: 2, "good-news": 1, fyi: 0 };
